   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e16-tractament', 'Tema 16. El tractament penitenciari, permisos i sortides') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e16-tractament' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte i finalitat del tractament penitenciari (arts. 59-61 LOGP)"},{"n":"2","title":"Principis del tractament (art. 62 LOGP) i informe pronòstic final (art. 67 LOGP)"},{"n":"3","title":"Juntes de tractament i equips tècnics (arts. 69 LOGP i 111 RP)"},{"n":"4","title":"L''equip multidisciplinari: concepte, composició i funcions (arts. 36-38 Decret 329/2006)"},{"n":"5","title":"Programes de tractament: activitats, sortides programades, comunitat terapèutica i programes especialitzats (arts. 110-117 RP)"},{"n":"6","title":"El programa individualitzat de tractament (PIT) (arts. 20.2 i 103.3 RP)"},{"n":"7","title":"Permisos de sortida ordinaris i extraordinaris (arts. 47-48 LOGP i 154-159 RP)"},{"n":"8","title":"Procediment de concessió dels permisos (arts. 160-162 RP)"},{"n":"9","title":"Treball i formació com a elements del tractament (art. 132 RP i RD 782/2001)"}]'::jsonb, '["Art. 59.1 LOGP: «El tratamiento penitenciario consiste en el conjunto de actividades directamente dirigidas a la consecución de la reeducación y reinserción social de los penados.»","Art. 61.1 LOGP: «Se fomentará que el interno participe en la planificación y ejecución de su tratamiento y colaborará para, en el futuro, ser capaz de llevar, con conciencia social, una vida sin delitos.»","Art. 62.c LOGP: «Será individualizado, consistiendo en la variable utilización de métodos médico-biológicos, psiquiátricos, psicológicos, pedagógicos y sociales, en relación a la personalidad del interno.»","Art. 111.1 RP: «Las tareas de observación, clasificación y tratamiento penitenciarios las realizarán las Juntas de Tratamiento y sus decisiones serán ejecutadas por los Equipos Técnicos»","Art. 36 Decret 329/2006: «Els equips multidisciplinaris seran les unitats d''estudi, proposta i execució amb que comptarà la Junta de Tractament.»","Art. 37.1 Decret 329/2006: «En els centres penitenciaris hi haurà, almenys, un equip multidisciplinari. L''equip multidisciplinari actuarà sota la direcció del/de la subdirector/a de Tractament.»","Art. 37.6 Decret 329/2006: «Els equips multidisciplinaris es reuniran amb una periodicitat setmanal»","Art. 38.1.a Decret 329/2006: «a) Elaborar el programa de tractament o el model d''intervenció individual dels/de les interns/es que tinguin assignats/ades.»","Art. 114.4 RP: «Las salidas programadas serán propuestas por la Junta de Tratamiento, que solicitará la aprobación del Centro Directivo y la posterior autorización del Juez de Vigilancia en aquellos supuestos en que la salida, por su duración y por el grado de clasificación del interno, sea competencia de este órgano judicial.»","Art. 114.5 RP: «Como regla general, la duración de las salidas programadas no será superior a dos días y, en ningún caso, se computarán dentro de los límites establecidos para los permisos ordinarios en el artículo 154.»","Art. 103.3 RP: «El protocolo de clasificación penitenciaria contendrá la propuesta razonada de grado y el programa individualizado de tratamiento»","Art. 154.1 RP: «Se podrán conceder, previo informe preceptivo del Equipo Técnico, permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad, hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente, siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta.»","Art. 155.1 RP: «En caso de fallecimiento o enfermedad grave de los padres, cónyuge, hijos, hermanos y otras personas íntimamente vinculadas con los internos o de alumbramiento de la esposa o persona con la que el recluso se halle ligado por similar relación de afectividad, así como por importantes y comprobados motivos de análoga naturaleza, se concederán, con las medidas de seguridad adecuadas en su caso, permisos de salida extraordinarios, salvo que concurran circunstancias excepcionales que lo impidan.»","Art. 161.1 RP: «Si la Junta de Tratamiento acuerda conceder el permiso solicitado por el interno, elevará dicho acuerdo, junto con el informe del Equipo Técnico, al Juez de Vigilancia o al Centro Directivo, según se trate de internos clasificados en segundo o tercer grado de tratamiento, respectivamente, para la autorización correspondiente.»","Art. 132 RP: «es un derecho y un deber del interno, constituye un elemento fundamental del tratamiento cuando así resulte de la formulación de un programa individualizado»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Concepte i finalitat del tractament penitenciari","blocks":[{"text":"El tractament penitenciari és el conjunt d''activitats directament dirigides a la reeducació i la reinserció social dels penats (art. 59.1 LOGP). Pretén fer de l''intern una persona amb la intenció i la capacitat de viure respectant la llei penal i de cobrir les seves necessitats, desenvolupant una actitud de respecte a si mateix i de responsabilitat individual i social (art. 59.2 LOGP). Els serveis de tractament han de conèixer i tractar les peculiaritats de personalitat i d''ambient del penat que hi siguin un obstacle, utilitzant tots els mètodes possibles amb respecte als drets constitucionals (art. 60 LOGP).","refs":[{"ref":"Art. 59.1 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"El tratamiento penitenciario consiste en el conjunto de actividades directamente dirigidas a la consecución de la reeducación y reinserción social de los penados."},{"ref":"Art. 59.2 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"El tratamiento pretende hacer del interno una persona con la intención y la capacidad de vivir respetando la Ley penal, así como de subvenir a sus necesidades."},{"ref":"Art. 60.Dos LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"deberán utilizarse, en tanto sea posible, todos los métodos de tratamiento y los medios que, respetando siempre los derechos constitucionales no afectados por la condena, puedan facilitar la obtención de dichas finalidades."}]},{"text":"El règim està al servei del tractament: el fi primordial del règim dels establiments de compliment és aconseguir l''ambient adequat per a l''èxit del tractament, i les funcions regimentals són mitjans i no finalitats en si mateixes (art. 71.1 LOGP).","refs":[{"ref":"Art. 71.1 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"El fin primordial del régimen de los establecimientos de cumplimiento es lograr en los mismos el ambiente adecuado para el éxito del tratamiento; en consecuencia, las funciones regimentales deben ser consideradas como medios y no como finalidades en sí mismas."}]}]},{"n":"2","title":"Principis del tractament i voluntarietat de l''intern","blocks":[{"text":"S''ha de fomentar que l''intern participi en la planificació i l''execució del seu tractament, perquè en el futur pugui portar, amb consciència social, una vida sense delictes (art. 61.1 LOGP; art. 112.1 RP). El professional de l''equip tècnic encarregat del seguiment l''informa dels objectius i dels mitjans i terminis per assolir-los. La participació és voluntària: l''intern pot rebutjar lliurement qualsevol tècnica d''estudi de la seva personalitat sense conseqüències disciplinàries, regimentals ni de regressió de grau; en aquest cas, la classificació es fa per observació directa, informes del personal i dades documentals (art. 112.3 i 112.4 RP).","refs":[{"ref":"Art. 61.Uno LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"Se fomentará que el interno participe en la planificación y ejecución de su tratamiento y colaborará para, en el futuro, ser capaz de llevar, con conciencia social, una vida sin delitos."},{"ref":"Art. 112.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El interno podrá rechazar libremente o no colaborar en la realización de cualquier técnica de estudio de su personalidad, sin que ello tenga consecuencias disciplinarias, regimentales ni de regresión de grado."}]},{"text":"Segons l''art. 62 LOGP, el tractament es basa en l''estudi científic de la constitució, el temperament, el caràcter, les aptituds i les actituds del subjecte, que porta a un judici global de la seva personalitat recollit en el protocol de l''intern; es guia pel diagnòstic de personalitat criminal i el judici pronòstic inicial; és individualitzat, amb mètodes medicobiològics, psiquiàtrics, psicològics, pedagògics i socials; és complex, perquè integra diversos mètodes en una direcció de conjunt; és programat; i és continu i dinàmic, depenent de l''evolució de la personalitat. Quan conclou el tractament o s''acosta la llibertat, s''emet un informe pronòstic final amb els resultats i un judici de probabilitat sobre el comportament futur en llibertat (art. 67 LOGP).","refs":[{"ref":"Art. 62.a LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"conducente a un enjuiciamiento global de la misma, que se recogerá en el protocolo del interno."},{"ref":"Art. 62.b LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"b) Guardará relación directa con un diagnóstico de personalidad criminal y con un juicio pronostico inicial"},{"ref":"Art. 62 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"c) Será individualizado, consistiendo en la variable utilización de métodos médico-biológicos, psiquiátricos, psicológicos, pedagógicos y sociales, en relación a la personalidad del interno. d) En general será complejo, exigiendo la integración de varios de los métodos citados en una dirección de conjunto y en el marco del régimen adecuado."},{"ref":"Art. 62.f LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"f) Será de carácter continuo y dinámico, dependiente de las incidencias en la evolución de la personalidad del interno durante el cumplimiento de la condena."},{"ref":"Art. 67 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"se emitirá un informe pronóstico final, en el que se manifestarán los resultados conseguidos por el tratamiento y un juicio de probabilidad sobre el comportamiento futuro del sujeto en libertad"}]}]},{"n":"3","title":"Òrgans del tractament: junta de tractament, equips i Central d''Observació","blocks":[{"text":"L''observació, la classificació i el tractament els fan les juntes de tractament i les seves decisions les executen els equips tècnics (art. 111.1 RP; art. 69 LOGP); s''hi pot demanar la col·laboració de ciutadans i entitats. Al Decret 329/2006, l''intern que ho demani té un tràmit d''audiència davant la junta en la classificació inicial, la progressió a tercer grau, la proposta del primer permís ordinari, la llibertat condicional i els beneficis penitenciaris; les propostes i informes de la junta es trameten, amb caràcter general, en un màxim de deu dies (art. 32 D329).","refs":[{"ref":"Art. 111.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las tareas de observación, clasificación y tratamiento penitenciarios las realizarán las Juntas de Tratamiento y sus decisiones serán ejecutadas por los Equipos Técnicos"},{"ref":"Art. 32.2 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"en els procediments de classificació inicial, progressió al tercer grau de classificació penitenciària, proposta del primer permís ordinari de sortida, llibertat condicional i beneficis penitenciaris."},{"ref":"Art. 32.3 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"Amb caràcter general, les propostes i informes previstos en aquest article s''hauran de trametre a l''autoritat administrativa o judicial que correspongui en el termini màxim de deu dies"}]},{"text":"L''equip tècnic d''especialistes de la Central Penitenciària d''Observació completa la tasca dels equips d''observació i tractament, resol dubtes i consultes tècniques del centre directiu i fa investigació criminològica (art. 70.1 LOGP). No resol recursos de classificació, que corresponen al jutge de vigilància.","refs":[{"ref":"Art. 70.1 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"a) Completar la labor de los Equipos de Observación y de Tratamiento en sus tareas específicas. b) Resolver las dudas y consultas de carácter técnico que se formulen por el centro directivo. c) Realizar una labor de investigación criminológica."}]}]},{"n":"4","title":"L''equip multidisciplinari: composició","blocks":[{"text":"A Catalunya, els equips tècnics s''anomenen equips multidisciplinaris (EMD): són les unitats d''estudi, proposta i execució de la junta de tractament, sota el control directe del coordinador dels equips o del cap de programes d''atenció especialitzada (art. 36 D329). A cada centre n''hi ha almenys un, sota la direcció del subdirector de Tractament (art. 37.1 D329). El consell de direcció proposa al centre directiu el nombre d''equips, la seva organització, el funcionament i la composició (art. 37.5 D329).","refs":[{"ref":"Art. 36 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"Els equips multidisciplinaris seran les unitats d''estudi, proposta i execució amb que comptarà la Junta de Tractament."},{"ref":"Art. 37.1 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"En els centres penitenciaris hi haurà, almenys, un equip multidisciplinari. L''equip multidisciplinari actuarà sota la direcció del/de la subdirector/a de Tractament."},{"ref":"Art. 37.5 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"el Consell de Direcció del centre proposarà al centre directiu la determinació del nombre d''equips multidisciplinaris de l''establiment penitenciari i la seva organització, el seu funcionament i la composició"}]},{"text":"En formen part el coordinador dels EMD o el cap de programes d''atenció especialitzada, el psicòleg, el jurista i l''educador adscrits, un docent, un metge, un treballador social, un monitor ocupacional o insertor laboral, un monitor esportiu i el cap d''unitat o coordinador d''unitat especialitzada (art. 37.2 D329). El director del centre no n''és membre. Les unitats que els tinguin assignats hi incorporen un psiquiatre, un infermer, un pedagog i un criminòleg (art. 37.3 D329). Els professionals d''entitats col·laboradores i de voluntariat poden assistir-hi amb veu i sense vot, amb sol·licitud i aprovació prèvia del consell de direcció. Els EMD es reuneixen setmanalment, fora de les franges d''intervenció amb els interns (art. 37.6 D329).","refs":[{"ref":"Art. 37.2 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"a) El/La coordinador/a dels equips multidisciplinaris, si n''hi ha, o el/la cap de programes d''atenció especialitzada. b) El/La psicòleg/oga adscrit/a a l''equip. c) El/La jurista adscrit/a a l''equip. d) L''educador/a adscrit/a a l''equip. e) Un/a docent. f) Un/a metge/essa. g) Un/a treballador/a social. h) Un/a monitor/a ocupacional i/o insertor/a laboral. i) Un/a monitor/a esportiu/iva. j) El/La cap d''unitat o el/la coordinador/a d''unitat especialitzada."},{"ref":"Art. 37.3 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"a) Un/a psiquiatre/a. b) Un/a infermer/a. c) Un/a pedagog/a. d) Un/a criminòleg/oga."},{"ref":"Art. 37.4 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"A les reunions de l''equip multidisciplinari hi podran assistir, amb la sol·licitud i aprovació prèvia del Consell de Direcció, amb veu però sense vot, els professionals de les entitats col·laboradores i els membres de les associacions de voluntariat"},{"ref":"Art. 37.6 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"Els equips multidisciplinaris es reuniran amb una periodicitat setmanal"}]}]},{"n":"5","title":"L''equip multidisciplinari: funcions","blocks":[{"text":"Les funcions dels EMD (art. 38 D329) són: elaborar el programa de tractament o el model d''intervenció individual (MII) dels interns assignats; analitzar directament els seus problemes i demandes; proposar a la junta la programació anual d''activitats, incloses les d''entitats i voluntariat; proposar a la junta la reducció, l''ajornament o la suspensió de sancions que pertorbin el tractament i la reducció dels terminis de cancel·lació; atendre les peticions i queixes sobre classificació, tractament o model d''intervenció; avaluar els objectius assolits i informar-ne la junta; executar les accions que els encomanin els òrgans de direcció; i fer l''orientació professional i la integració sociolaboral. No resolen expedients disciplinaris, que són competència de la comissió disciplinària.","refs":[{"ref":"Art. 38.1 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"a) Elaborar el programa de tractament o el model d''intervenció individual dels/de les interns/es que tinguin assignats/ades."},{"ref":"Art. 38.1.d D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"Proposar a la Junta de Tractament la reducció, ajornament de l''execució o suspensió de l''efectivitat de les sancions disciplinàries que puguin pertorbar el tractament"},{"ref":"Art. 38.1 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"c) Proposar a la Junta de Tractament la programació anual d''activitats del seu àmbit d''actuació […] e) Atendre les peticions i queixes que formulin els/les interns/es respecte de la seva classificació, tractament o model d''intervenció."}]}]},{"n":"6","title":"El programa individualitzat de tractament (PIT)","blocks":[{"text":"A l''ingrés, la junta de tractament, amb informe previ de l''equip tècnic, contrasta les dades del protocol i formula un programa individualitzat de tractament sobre formació, treball, relacions i altres àmbits carencials (art. 20.2 RP). El protocol de classificació conté la proposta raonada de grau i el PIT, que cobreix les necessitats i carències detectades i assenyala expressament destinacions, activitats, programes educatius, treball i activitats ocupacionals (art. 103.3 RP). A Catalunya, el Decret 329/2006 parla també del model d''intervenció individual, que elabora l''EMD (art. 38.1.a D329).","refs":[{"ref":"Art. 20.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Por la Junta de Tratamiento, previo informe del Equipo Técnico, se contrastarán los datos del protocolo y se formulará un programa individualizado de tratamiento"},{"ref":"Art. 103.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El protocolo de clasificación penitenciaria contendrá la propuesta razonada de grado y el programa individualizado de tratamiento"}]},{"text":"Les activitats educatives, formatives, socioculturals i esportives les determina el consell de direcció a partir dels programes individualitzats elaborats per les juntes (art. 118.1 RP). Les certificacions dels cursos s''expedeixen a petició de l''intern i no poden indicar que s''han obtingut en un establiment penitenciari (art. 119.2 RP).","refs":[{"ref":"Art. 118.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las actividades educativas, formativas, socioculturales y deportivas se determinarán por el Consejo de Dirección, teniendo en cuenta los planes de actuación del Centro Directivo, a partir de los programas individualizados elaborados por las Juntas de Tratamiento."},{"ref":"Art. 119.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se expedirán a solicitud del interno certificaciones acreditativas de las enseñanzas, cursos o actividades desarrollados, que no deberán contener indicación alguna relativa a su obtención en un Establecimiento penitenciario."}]}]},{"n":"7","title":"Programes de tractament","blocks":[{"text":"L''Administració dissenya programes formatius per desenvolupar les aptituds i compensar carències, utilitza programes i tècniques psicosocials per millorar les capacitats dels interns i potencia els contactes amb l''exterior amb els recursos de la comunitat (art. 110 RP). Les activitats de tractament es fan dins i fora dels centres (art. 113.1 RP). Per a grups que ho requereixin es poden organitzar comunitats terapèutiques; si el centre directiu ho autoritza, la junta de tractament que les dirigeix assumeix les funcions del consell de direcció i de la comissió disciplinària, excepte les economicoadministratives (art. 115.2 RP).","refs":[{"ref":"Art. 110 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"c) Potenciará y facilitará los contactos del interno con el exterior contando, siempre que sea posible, con los recursos de la comunidad como instrumentos fundamentales en las tareas de reinserción."},{"ref":"Art. 113.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las actividades de tratamiento se realizarán tanto en el interior de los Centros penitenciarios como fuera de ellos"},{"ref":"Art. 115.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Siempre que el Centro Directivo autorice la constitución de uno de estos grupos, la Junta de Tratamiento que esté al frente del mismo asumirá las funciones que tienen atribuidas el Consejo de Dirección y la Comisión Disciplinaria del Centro penitenciario, con exclusión de las que se refieran a los aspectos económico-administrativos."}]},{"text":"Tot intern amb dependència de substàncies que ho vulgui ha de poder seguir programes de deshabituació, sigui quina sigui la seva situació processal (art. 116.1 RP). Els programes per a condemnats per delictes contra la llibertat sexual es fan segons diagnòstic previ, són sempre voluntaris i no poden comportar marginació (art. 116.4 RP). Les juntes valoren l''aprofitament dels programes específics per a condemnats per violència contra la infància en les progressions, els permisos i la llibertat condicional (art. 66 bis LOGP).","refs":[{"ref":"Art. 116.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Todo interno con dependencia de sustancias psicoactivas que lo desee, debe tener a su alcance la posibilidad de seguir programas de tratamiento y deshabituación, con independencia de su situación procesal y de sus vicisitudes penales y penitenciarias."},{"ref":"Art. 116.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El seguimiento de estos programas será siempre voluntario y no podrá suponer la marginación de los internos afectados en los Centros penitenciarios."},{"ref":"Art. 66 bis LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"Las Juntas de Tratamiento valorarán, en las progresiones de grado, concesión de permisos y concesión de la libertad condicional, el seguimiento y aprovechamiento de dichos programas específicos"}]},{"text":"Els penats de segon grau de baixa perillositat i sense risc de trencament poden anar regularment a una institució exterior per seguir un programa d''atenció especialitzada (art. 117 RP). Cal que la junta ho planifiqui amb l''intern i que aquest hi consenti; cada sortida diària no pot superar vuit hores i el programa requereix autorització del jutge de vigilància. El control no pot consistir en control personal per membres de les forces de seguretat, i l''intern pot renunciar voluntàriament al programa.","refs":[{"ref":"Art. 117 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los internos clasificados en segundo grado de tratamiento que presenten un perfil de baja peligrosidad social y no ofrezcan riesgos de quebrantamiento de condena […] que no podrán consistir en control personal por miembros de los Cuerpos y Fuerzas de Seguridad del Estado."},{"ref":"Art. 117.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La duración de cada salida diaria no excederá de ocho horas, y el programa del que forme parte requerirá la autorización del Juez de Vigilancia."}]}]},{"n":"8","title":"Sortides programades","blocks":[{"text":"Les sortides programades són activitats concretes de tractament a l''exterior. Els interns hi van sempre acompanyats per personal del centre o d''altres institucions, o per voluntaris que habitualment fan activitats de tractament (art. 114.2 RP). Els requisits són els dels permisos ordinaris de l''art. 154 RP (art. 114.3 RP). Les proposa la junta de tractament, que en demana l''aprovació al centre directiu i, si per la durada i el grau és competent, l''autorització posterior al jutge de vigilància (art. 114.4 RP). Com a regla general no duren més de dos dies i no computen en els límits dels permisos ordinaris (art. 114.5 RP).","refs":[{"ref":"Art. 114.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En todo caso, los internos serán acompañados por personal del Centro penitenciario o de otras instituciones o por voluntarios que habitualmente realicen actividades relacionadas con el tratamiento penitenciario de los reclusos."},{"ref":"Art. 114.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los requisitos necesarios para la concesión de salidas programadas serán los establecidos para los permisos ordinarios de salida en el artículo 154 de este Reglamento."},{"ref":"Art. 114.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las salidas programadas serán propuestas por la Junta de Tratamiento, que solicitará la aprobación del Centro Directivo y la posterior autorización del Juez de Vigilancia"},{"ref":"Art. 114.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Como regla general, la duración de las salidas programadas no será superior a dos días y, en ningún caso, se computarán dentro de los límites establecidos para los permisos ordinarios en el artículo 154."}]}]},{"n":"9","title":"Permisos de sortida ordinaris i extraordinaris","blocks":[{"text":"Els permisos ordinaris preparen per a la vida en llibertat: amb informe preceptiu de l''equip tècnic, es poden concedir als penats de segon o tercer grau permisos de fins a set dies, fins a un total de trenta-sis o quaranta-vuit dies l''any respectivament, si han extingit la quarta part de la condemna i no tenen mala conducta (art. 47.2 LOGP; art. 154.1 RP). Els límits es distribueixen en els dos semestres naturals: fins a divuit dies per semestre en segon grau i vint-i-quatre en tercer (art. 154.2 RP). No hi computen les sortides de cap de setmana del règim obert, les sortides programades ni els permisos extraordinaris (art. 154.3 RP). Els preventius poden tenir permisos amb aprovació de l''autoritat judicial (art. 48 LOGP; art. 159 RP).","refs":[{"ref":"Art. 154.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se podrán conceder, previo informe preceptivo del Equipo Técnico, permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad, hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente, siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta."},{"ref":"Art. 154.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se distribuirán, como regla general, en los dos semestres naturales de cada año, concediendo en cada uno de ellos hasta dieciocho y veinticuatro días, respectivamente."},{"ref":"Art. 154.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Dentro de los indicados límites no se computarán las salidas de fin de semana propias del régimen abierto ni las salidas programadas que se regulan en el artículo 114 de este Reglamento, ni los permisos extraordinarios regulados en el artículo siguiente."},{"ref":"Art. 48 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"Los permisos a que se refiere el artículo anterior podrán ser concedidos asimismo a internos preventivos con la aprobación, en cada caso, de la autoridad judicial correspondiente."}]},{"text":"Els permisos extraordinaris es concedeixen, amb les mesures de seguretat adequades, per defunció o malaltia greu de pares, cònjuge, fills, germans i altres persones íntimament vinculades, per naixement d''un fill o per motius importants i comprovats de naturalesa anàloga, llevat de circumstàncies excepcionals (art. 155.1 RP). Per als de primer grau cal autorització expressa del jutge de vigilància (art. 155.3 RP). Per a consulta ambulatòria extrapenitenciària, els de segon i tercer grau poden tenir permisos de fins a dotze hores; si l''ingrés hospitalari dura més de dos dies, la pròrroga l''autoritza el jutge de vigilància (segon grau) o el centre directiu (tercer grau) (art. 155.4 RP).","refs":[{"ref":"Art. 155.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En caso de fallecimiento o enfermedad grave de los padres, cónyuge, hijos, hermanos y otras personas íntimamente vinculadas con los internos o de alumbramiento de la esposa o persona con la que el recluso se halle ligado por similar relación de afectividad, así como por importantes y comprobados motivos de análoga naturaleza, se concederán, con las medidas de seguridad adecuadas en su caso, permisos de salida extraordinarios"},{"ref":"Art. 155.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Cuando se trate de internos clasificados en primer grado será necesaria la autorización expresa del Juez de Vigilancia."},{"ref":"Art. 155.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"permisos extraordinarios de salida de hasta doce horas de duración para consulta ambulatoria extrapenitenciaria de los penados clasificados en segundo o tercer grado"},{"ref":"Art. 155.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"si el interno tuviera que permanecer ingresado más de dos días, la prolongación del permiso por el tiempo necesario deberá ser autorizada por el Juez de Vigilancia cuando se trate de penados clasificados en segundo grado o por el Centro Directivo para los clasificados en tercer grado."}]}]},{"n":"10","title":"Procediment de concessió, suspensió i revocació dels permisos","blocks":[{"text":"La sol·licitud l''informa l''equip tècnic, que comprova els requisits, valora la finalitat i fixa condicions i controls (art. 160.1 RP). L''informe ha de ser desfavorable si, per la trajectòria delictiva, la personalitat anòmala o variables qualitatives desfavorables, és probable el trencament de condemna, nous delictes o una repercussió negativa de la sortida (art. 156.1 RP). La junta de tractament acorda la concessió o denegació (art. 160.2 RP). Si concedeix, eleva l''acord al jutge de vigilància (segon grau) o al centre directiu (tercer grau) (art. 161.1 RP); els permisos ordinaris de fins a dos dies els autoritza el centre directiu (art. 161.2 RP), ja que el jutge autoritza els superiors a dos dies, excepte els del tercer grau (art. 76.2.i LOGP). En urgència, el director pot autoritzar el permís extraordinari (art. 161.4 RP). La denegació es notifica motivadament amb indicació del dret de queixa al jutge de vigilància (art. 162 RP).","refs":[{"ref":"Art. 156.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El informe preceptivo del Equipo Técnico será desfavorable cuando, por la peculiar trayectoria delictiva, la personalidad anómala del interno o por la existencia de variables cualitativas desfavorables, resulte probable el quebrantamiento de la condena, la comisión de nuevos delitos o una repercusión negativa de la salida"},{"ref":"Art. 161.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"elevará dicho acuerdo, junto con el informe del Equipo Técnico, al Juez de Vigilancia o al Centro Directivo, según se trate de internos clasificados en segundo o tercer grado de tratamiento, respectivamente, para la autorización correspondiente."},{"ref":"Art. 161.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los permisos ordinarios a penados de hasta dos días de duración serán autorizados por el Centro Directivo."},{"ref":"Art. 76.2.i LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"i) Autorizar los permisos de salida cuya duración sea superior a dos días, excepto de los clasificados en tercer grado."},{"ref":"Art. 161.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En los supuestos de urgencia, el permiso extraordinario podrá ser autorizado por el Director del Establecimiento, previa consulta al Centro Directivo si hubiere lugar a ello, y sin perjuicio de comunicar a la Junta de Tratamiento la autorización concedida."},{"ref":"Art. 162 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Cuando la Junta de Tratamiento acuerde denegar el permiso solicitado por el interno, se notificará a éste la decisión motivada con indicación expresa de su derecho a acudir en vía de queja al Juez de Vigilancia Penitenciaria."}]},{"text":"Si abans de gaudir el permís canvien les circumstàncies, la direcció el pot suspendre provisionalment i motivadament, i ho comunica a l''autoritat competent (art. 157.1 RP). Si l''intern aprofita el permís per fugir o comet un delicte, el permís queda sense efecte, sens perjudici de les conseqüències penals i penitenciàries i de la valoració negativa per a futurs permisos (art. 157.2 RP).","refs":[{"ref":"Art. 157.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"la Dirección podrá suspender motivadamente con carácter provisional el permiso, poniéndose en conocimiento de la Autoridad administrativa o judicial competente la suspensión para que resuelva lo que proceda."},{"ref":"Art. 157.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Si el interno aprovechase el disfrute de cualquier clase de permiso para fugarse o cometiese un nuevo delito durante el mismo, quedará sin efecto el permiso concedido"}]}]},{"n":"11","title":"El treball com a element del tractament","blocks":[{"text":"El treball productiu per compte d''altri és un dret i un deure de l''intern, constitueix un element fonamental del tractament quan ho prevegi el programa individualitzat i prepara per a l''accés al mercat laboral (art. 132 RP). En els tallers productius, la junta de tractament, com a òrgan administratiu competent, adjudica els llocs de treball, amb prioritat per als interns que tinguin prevista l''activitat laboral en el seu PIT (art. 3.2 RD 782/2001).","refs":[{"ref":"Art. 132 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"es un derecho y un deber del interno, constituye un elemento fundamental del tratamiento cuando así resulte de la formulación de un programa individualizado"},{"ref":"Art. 3.2 RD 782/2001","law":"RD 782/2001","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171","quote":"La Junta de Tratamiento, como órgano administrativo competente, adjudicará los puestos a los internos, siguiendo el siguiente orden de prelación: 1.º Los internos en cuyo programa individualizado de tratamiento se contemple el desarrollo de una actividad laboral."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Tractament: conjunt d''activitats dirigides a la reeducació i la reinserció social dels penats.","refs":[{"ref":"Art. 59.1 LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"El tratamiento penitenciario consiste en el conjunto de actividades directamente dirigidas a la consecución de la reeducación y reinserción social de los penados."}]},{"text":"Rebutjar les tècniques d''estudi de la personalitat no té conseqüències disciplinàries, regimentals ni de regressió.","refs":[{"ref":"Art. 112.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"sin que ello tenga consecuencias disciplinarias, regimentales ni de regresión de grado."}]},{"text":"EMD: sota la direcció del subdirector de Tractament i reunió setmanal.","refs":[{"ref":"Art. 37.6 D329","law":"Decret 329/2006","url":"https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252","quote":"Els equips multidisciplinaris es reuniran amb una periodicitat setmanal"}]},{"text":"Sortides programades: acompanyats, regla general màxim dos dies i no computen com a permisos.","refs":[{"ref":"Art. 114.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"la duración de las salidas programadas no será superior a dos días"}]},{"text":"Permisos ordinaris: fins a set dies; 36 dies l''any (segon grau) o 48 (tercer); quarta part complerta i sense mala conducta.","refs":[{"ref":"Art. 47.Dos LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados de segundo y tercer grado, respectivamente, siempre que hayan extinguido la cuarta parte de la condena y no observen mala conducta."}]},{"text":"Distribució semestral: 18 dies (segon grau) i 24 dies (tercer grau).","refs":[{"ref":"Art. 154.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"hasta dieciocho y veinticuatro días, respectivamente."}]},{"text":"Consulta ambulatòria: permís extraordinari de fins a dotze hores.","refs":[{"ref":"Art. 155.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"de hasta doce horas de duración"}]},{"text":"Autoritzen: jutge de vigilància (segon grau, més de dos dies) i centre directiu (tercer grau i fins a dos dies).","refs":[{"ref":"Art. 161.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los permisos ordinarios a penados de hasta dos días de duración serán autorizados por el Centro Directivo."}]},{"text":"Denegació del permís: notificació motivada i queixa al jutge de vigilància.","refs":[{"ref":"Art. 162 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"con indicación expresa de su derecho a acudir en vía de queja al Juez de Vigilancia Penitenciaria."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, 'Otras normas citadas: LOGP (https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708), Decret 329/2006 (https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252)'
  from public.topics t where t.slug = 'pcat-e16-tractament'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e17-regim-disciplinari', 'Tema 17. El règim disciplinari dels interns') on conflict (slug) do nothing;
