   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e19-criminologia', 'Tema 19. Delinqüència i noves tipologies') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e19-criminologia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La delinqüència organitzada"},{"n":"1.1","title":"Organitzacions criminals: concepte i penes (art. 570 bis CP)"},{"n":"1.2","title":"Grups criminals (art. 570 ter CP) i disposicions comunes (art. 570 quater CP)"},{"n":"2","title":"La delinqüència econòmica"},{"n":"2.1","title":"El blanqueig de capitals (arts. 301-304 CP)"},{"n":"2.2","title":"L''estafa i l''estafa informàtica (arts. 248 i 249 CP)"},{"n":"3","title":"La delinqüència terrorista (arts. 571-580 bis CP)"},{"n":"3.1","title":"Organitzacions i grups terroristes i delictes de terrorisme (arts. 571-573 bis CP)"},{"n":"3.2","title":"Col·laboració, enaltiment, provocació i conseqüències accessòries (arts. 577-580 CP)"},{"n":"4","title":"La ciberdelinqüència"},{"n":"4.1","title":"Accés il·legal i interceptació de dades (arts. 197 bis i 197 ter CP)"},{"n":"4.2","title":"Danys informàtics (arts. 264-264 quater CP)"}]'::jsonb, '["Art. 570 bis.1 Codi penal: «A los efectos de este Código se entiende por organización criminal la agrupación formada por más de dos personas con carácter estable o por tiempo indefinido, que de manera concertada y coordinada se repartan diversas tareas o funciones con el fin de cometer delitos.»","Art. 570 ter.1 Codi penal: «A los efectos de este Código se entiende por grupo criminal la unión de más de dos personas que, sin reunir alguna o algunas de las características de la organización criminal definida en el artículo anterior, tenga por finalidad o por objeto la perpetración concertada de delitos.»","Art. 570 quáter.1 Codi penal: «Los jueces o tribunales, en los supuestos previstos en este Capítulo y el siguiente, acordarán la disolución de la organización o grupo y, en su caso, cualquier otra de las consecuencias de los artículos 33.7 y 129 de este Código.»","Art. 301.1 Codi penal: «El que adquiera, posea, utilice, convierta, o transmita bienes, sabiendo que éstos tienen su origen en una actividad delictiva, cometida por él o por cualquiera tercera persona, o realice cualquier otro acto para ocultar o encubrir su origen ilícito, o para ayudar a la persona que haya participado en la infracción o infracciones a eludir las consecuencias legales de sus actos, será castigado con la pena de prisión de seis meses a seis años y multa del tanto al triplo del valor de los bienes.»","Art. 301.3 Codi penal: «Si los hechos se realizasen por imprudencia grave, la pena será de prisión de seis meses a dos años y multa del tanto al triplo.»","Art. 248 Codi penal: «Cometen estafa los que, con ánimo de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno.»","Art. 249.1.a) Codi penal: «Los que, con ánimo de lucro, obstaculizando o interfiriendo indebidamente en el funcionamiento de un sistema de información o introduciendo, alterando, borrando, transmitiendo o suprimiendo indebidamente datos informáticos o valiéndose de cualquier otra manipulación informática o artificio semejante, consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro.»","Art. 571 Codi penal: «A los efectos de este Código se considerarán organizaciones o grupos terroristas aquellas agrupaciones que, reuniendo las características respectivamente establecidas en el párrafo segundo del apartado 1 del artículo 570 bis y en el párrafo segundo del apartado 1 del artículo 570 ter, tengan por finalidad o por objeto la comisión de alguno de los delitos tipificados en la sección siguiente.»","Art. 572 Codi penal: «Quienes promovieran, constituyeran, organizaran o dirigieran una organización o grupo terrorista serán castigados con las penas de prisión de ocho a quince años e inhabilitación absoluta durante el tiempo de la condena.»","Art. 573.1 Codi penal: «1.ª Subvertir el orden constitucional, o suprimir o desestabilizar gravemente el funcionamiento de las instituciones políticas o de las estructuras económicas o sociales del Estado, u obligar a los poderes públicos a realizar un acto o a abstenerse de hacerlo. 2.ª Alterar gravemente la paz pública. 3.ª Desestabilizar gravemente el funcionamiento de una organización internacional. 4.ª Provocar un estado de terror en la población o en una parte de ella.»","Art. 573 bis.2 Codi penal: «Las penas se impondrán en su mitad superior si los hechos se cometieran contra las personas mencionadas en el apartado 3 del artículo 550 o contra miembros de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas o contra empleados públicos que presten servicio en instituciones penitenciarias.»","Art. 578.1 Codi penal: «El enaltecimiento o la justificación públicos de los delitos comprendidos en los artículos 572 a 577 o de quienes hayan participado en su ejecución, o la realización de actos que entrañen descrédito, menosprecio o humillación de las víctimas de los delitos terroristas o de sus familiares, se castigará con la pena de prisión de uno a tres años y multa de doce a dieciocho meses.»","Art. 580 Codi penal: «En todos los delitos de terrorismo, la condena de un juez o tribunal extranjero será equiparada a las sentencias de los jueces o tribunales españoles a los efectos de aplicación de la agravante de reincidencia.»","Art. 197 bis.1 Codi penal: «El que por cualquier medio o procedimiento, vulnerando las medidas de seguridad establecidas para impedirlo, y sin estar debidamente autorizado, acceda o facilite a otro el acceso al conjunto o una parte de un sistema de información o se mantenga en él en contra de la voluntad de quien tenga el legítimo derecho a excluirlo, será castigado con pena de prisión de seis meses a dos años.»","Art. 264.1 Codi penal: «El que por cualquier medio, sin autorización y de manera grave borrase, dañase, deteriorase, alterase, suprimiese o hiciese inaccesibles datos informáticos, programas informáticos o documentos electrónicos ajenos, cuando el resultado producido fuera grave, será castigado con la pena de prisión de seis meses a tres años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Delinqüència i noves tipologies: el marc del Codi penal","blocks":[{"text":"La criminologia estudia el delicte, el delinqüent, la víctima i el control social. Les «noves tipologies» de l''epígraf (delinqüència organitzada, econòmica, terrorista i ciberdelinqüència) tenen en comú que van més enllà de l''autor individual: s''organitzen en estructures estables, persegueixen beneficis econòmics o polítics i fan servir les tecnologies. Aquests apunts les estudien a partir de com les defineix i castiga el Codi penal, que és la font oficial del tema i el que pregunta l''examen (a la JU033 va sortir el concepte d''organització criminal). Un element que les uneix és que el Codi agreuja moltes figures quan es cometen en el si d''una organització o grup criminal: per exemple, en els delictes contra la intimitat s''apliquen les penes superiors en grau.","refs":[{"ref":"Art. 197 quater CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si los hechos descritos en este Capítulo se hubieran cometido en el seno de una organización o grupo criminal, se aplicarán respectivamente las penas superiores en grado."}]}]},{"n":"2","title":"La delinqüència organitzada: l''organització criminal","blocks":[{"text":"Per al Codi, organització criminal és l''agrupació formada per més de dues persones (per tant, tres o més) amb caràcter estable o per temps indefinit que, de manera concertada i coordinada, es reparteixen diverses tasques o funcions amb la finalitat de cometre delictes (art. 570 bis.1). Els elements clau són, doncs, pluralitat, estabilitat, repartiment de tasques i finalitat delictiva.","refs":[{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A los efectos de este Código se entiende por organización criminal la agrupación formada por más de dos personas con carácter estable o por tiempo indefinido, que de manera concertada y coordinada se repartan diversas tareas o funciones con el fin de cometer delitos."}]},{"text":"Penes: els qui promouen, constitueixen, organitzen, coordinen o dirigeixen l''organització, presó de quatre a vuit anys si té per objecte cometre delictes greus i de tres a sis anys en els altres casos; els qui hi participen activament, en formen part o hi cooperen econòmicament, presó de dos a cinc anys si la finalitat són delictes greus i d''un a tres anys en els altres casos.","refs":[{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Quienes promovieren, constituyeren, organizaren, coordinaren o dirigieren una organización criminal serán castigados con la pena de prisión de cuatro a ocho años si aquélla tuviere por finalidad u objeto la comisión de delitos graves"},{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"y con la pena de prisión de tres a seis años en los demás casos"},{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"y quienes participaren activamente en la organización, formaren parte de ella o cooperaren económicamente o de cualquier otro modo con la misma serán castigados con las penas de prisión de dos a cinco años si tuviere como fin la comisión de delitos graves, y con la pena de prisión de uno a tres años en los demás casos."}]},{"text":"Les penes s''imposen en la meitat superior quan l''organització està formada per un nombre elevat de persones, disposa d''armes o instruments perillosos o disposa de mitjans tecnològics avançats de comunicació o transport especialment aptes per facilitar els delictes o la impunitat; si n''hi concorren dues o més, les penes superiors en grau (art. 570 bis.2). També s''imposen en la meitat superior si els delictes són contra la vida o la integritat de les persones, la llibertat, la llibertat i indemnitat sexuals o el tràfic d''éssers humans (art. 570 bis.3). Tenir la seu a l''estranger no és cap agreujant.","refs":[{"ref":"Art. 570 bis.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"a) esté formada por un elevado número de personas. b) disponga de armas o instrumentos peligrosos. c) disponga de medios tecnológicos avanzados de comunicación o transporte que por sus características resulten especialmente aptos para facilitar la ejecución de los delitos o la impunidad de los culpables."},{"ref":"Art. 570 bis.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se impondrán en su mitad superior las penas respectivamente previstas en este artículo si los delitos fueren contra la vida o la integridad de las personas, la libertad, la libertad e indemnidad sexuales o la trata de seres humanos."}]}]},{"n":"3","title":"El grup criminal i les disposicions comunes","blocks":[{"text":"El grup criminal és la unió de més de dues persones que, sense reunir alguna o algunes de les característiques de l''organització criminal (per exemple, l''estabilitat o el repartiment de tasques), té per finalitat o objecte la perpetració concertada de delictes (art. 570 ter.1). Les penes són menors: de dos a quatre anys (delictes greus de l''art. 570 bis.3) o d''un a tres anys (menys greus); de sis mesos a dos anys si la finalitat és qualsevol altre delicte greu, i de tres mesos a un any per a altres delictes menys greus o la comissió reiterada de delictes lleus.","refs":[{"ref":"Art. 570 ter.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A los efectos de este Código se entiende por grupo criminal la unión de más de dos personas que, sin reunir alguna o algunas de las características de la organización criminal definida en el artículo anterior, tenga por finalidad o por objeto la perpetración concertada de delitos."},{"ref":"Art. 570 ter.1.b CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"b) Con la pena de seis meses a dos años de prisión si la finalidad del grupo es cometer cualquier otro delito grave."}]},{"text":"Disposicions comunes (art. 570 quater): el jutge acorda la dissolució de l''organització o grup i, si escau, les altres conseqüències dels arts. 33.7 i 129; s''imposa també una inhabilitació especial per a activitats econòmiques relacionades per un temps superior entre sis i vint anys al de la pena privativa de llibertat; les normes s''apliquen a tota organització o grup que actuï a Espanya encara que s''hagi constituït, estigui assentat o actuï a l''estranger, i es pot rebaixar la pena en un o dos graus a qui abandoni voluntàriament l''activitat i col·labori activament amb les autoritats (per obtenir proves decisives, impedir l''actuació del grup o evitar un delicte).","refs":[{"ref":"Art. 570 quater.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los jueces o tribunales, en los supuestos previstos en este Capítulo y el siguiente, acordarán la disolución de la organización o grupo y, en su caso, cualquier otra de las consecuencias de los artículos 33.7 y 129 de este Código."},{"ref":"Art. 570 quater.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"por un tiempo superior entre seis y veinte años al de la duración de la pena de privación de libertad impuesta en su caso"},{"ref":"Art. 570 quater.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las disposiciones de este Capítulo serán aplicables a toda organización o grupo criminal que lleve a cabo cualquier acto penalmente relevante en España, aunque se hayan constituido, estén asentados o desarrollen su actividad en el extranjero."},{"ref":"Art. 570 quater.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"bien para obtener pruebas decisivas para la identificación o captura de otros responsables o para impedir la actuación o el desarrollo de las organizaciones o grupos a que haya pertenecido, bien para evitar la perpetración de un delito que se tratara de cometer en el seno o a través de dichas organizaciones o grupos."}]}]},{"n":"4","title":"La delinqüència econòmica: el blanqueig de capitals","blocks":[{"text":"El blanqueig consisteix a adquirir, posseir, utilitzar, convertir o transmetre béns sabent que provenen d''una activitat delictiva (comesa pel mateix autor o per un tercer), o fer qualsevol acte per ocultar-ne l''origen il·lícit o ajudar el partícip a eludir-ne les conseqüències legals. La pena és de presó de sis mesos a sis anys i multa del tant al triple del valor dels béns, i s''imposa en la meitat superior si els béns provenen del tràfic de drogues (arts. 368 a 372) (art. 301.1).","refs":[{"ref":"Art. 301.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que adquiera, posea, utilice, convierta, o transmita bienes, sabiendo que éstos tienen su origen en una actividad delictiva, cometida por él o por cualquiera tercera persona, o realice cualquier otro acto para ocultar o encubrir su origen ilícito, o para ayudar a la persona que haya participado en la infracción o infracciones a eludir las consecuencias legales de sus actos, será castigado con la pena de prisión de seis meses a seis años y multa del tanto al triplo del valor de los bienes."},{"ref":"Art. 301.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La pena se impondrá en su mitad superior cuando los bienes tengan su origen en alguno de los delitos relacionados con el tráfico de drogas tóxicas, estupefacientes o sustancias psicotrópicas descritos en los artículos 368 a 372 de este Código."}]},{"text":"El blanqueig també es castiga per imprudència greu, amb presó de sis mesos a dos anys i multa del tant al triple (art. 301.3). Als qui pertanyen a una organització dedicada al blanqueig se''ls imposa la pena en la meitat superior, i als caps, administradors o encarregats, la superior en grau (art. 302.1). Si el fet el comet una autoritat o un agent seu, s''hi afegeix la inhabilitació absoluta de deu a vint anys (art. 303). La provocació, la conspiració i la proposició es castiguen amb la pena inferior en un o dos graus (art. 304).","refs":[{"ref":"Art. 301.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Si los hechos se realizasen por imprudencia grave, la pena será de prisión de seis meses a dos años y multa del tanto al triplo."},{"ref":"Art. 302.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"se impondrán las penas privativas de libertad en su mitad superior a las personas que pertenezca a una organización dedicada a los fines señalados en los mismos, y la pena superior en grado a los jefes, administradores o encargados de las referidas organizaciones."},{"ref":"Art. 303 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se impondrá la pena de inhabilitación absoluta de diez a veinte años cuando los referidos hechos fueren realizados por autoridad o agente de la misma."},{"ref":"Art. 304 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La provocación, la conspiración y la proposición para cometer los delitos previstos en los artículos 301 a 303 se castigará, respectivamente, con la pena inferior en uno o dos grados."}]}]},{"n":"5","title":"Altres delictes econòmics: estafa, corrupció entre particulars i frau a les hisendes públiques","blocks":[{"text":"Cometen estafa els qui, amb ànim de lucre, utilitzen un engany suficient per produir error en una altra persona i la indueixen a fer un acte de disposició en perjudici propi o d''altri (art. 248). La pena és de presó de sis mesos a tres anys i, si el defraudat no passa de 400 euros, multa d''un a tres mesos. La LO 1/2026 ha afegit que, si el culpable havia estat condemnat executòriament almenys per tres delictes de la mateixa naturalesa del capítol, un d''ells com a mínim lleu, s''imposa la pena de presó.","refs":[{"ref":"Art. 248 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Cometen estafa los que, con ánimo de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno. Los reos de estafa serán castigados con la pena de prisión de seis meses a tres años."},{"ref":"Art. 248 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"No obstante, en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este capítulo, y siendo al menos uno de ellos leve, se impondrá la pena prevista en el párrafo segundo del presente artículo."}]},{"text":"La corrupció entre particulars (art. 286 bis) es castiga amb presó de sis mesos a quatre anys, inhabilitació especial per a la indústria o el comerç d''un a sis anys i multa del tant al triple del benefici. Els delictes contra la Hisenda Pública i la Seguretat Social tenen llindars quantitatius: el frau tributari exigeix una quota defraudada superior a cent vint mil euros (art. 305.1), i és agreujat, entre altres casos, si supera els sis-cents mil euros o es comet en el si d''una organització o grup criminal (art. 305 bis); el frau a la Seguretat Social, més de cinquanta mil euros (art. 307.1), i el frau de subvencions, més de cent mil euros (art. 308.1).","refs":[{"ref":"Art. 286 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de prisión de seis meses a cuatro años, inhabilitación especial para el ejercicio de industria o comercio por tiempo de uno a seis años y multa del tanto al triplo del valor del beneficio o ventaja."},{"ref":"Art. 305.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"exceda de ciento veinte mil euros será castigado con la pena de prisión de uno a cinco años"},{"ref":"Art. 305 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"a) Que la cuantía de la cuota defraudada exceda de seiscientos mil euros. b) Que la defraudación se haya cometido en el seno de una organización o de un grupo criminal."},{"ref":"Art. 307.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"siempre que la cuantía de las cuotas defraudadas o de las devoluciones o deducciones indebidas exceda de cincuenta mil euros será castigado con la pena de prisión de uno a cinco años"},{"ref":"Art. 308.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que obtenga subvenciones o ayudas de las Administraciones Públicas, incluida la Unión Europea, en una cantidad o por un valor superior a cien mil euros falseando las condiciones requeridas para su concesión u ocultando las que la hubiesen impedido será castigado con la pena de prisión de uno a cinco años y multa del tanto al séxtuplo de su importe"}]}]},{"n":"6","title":"La delinqüència terrorista: organitzacions i grups terroristes","blocks":[{"text":"Són organitzacions o grups terroristes les agrupacions que reuneixen les característiques de l''organització criminal (art. 570 bis) o del grup criminal (art. 570 ter) i tenen per finalitat o objecte cometre algun dels delictes de terrorisme (art. 571). Els qui promouen, constitueixen, organitzen o dirigeixen una organització o grup terrorista són castigats amb presó de vuit a quinze anys i inhabilitació absoluta durant la condemna; els qui hi participen activament o en formen part, amb presó de sis a dotze anys i inhabilitació absoluta (art. 572).","refs":[{"ref":"Art. 571 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A los efectos de este Código se considerarán organizaciones o grupos terroristas aquellas agrupaciones que, reuniendo las características respectivamente establecidas en el párrafo segundo del apartado 1 del artículo 570 bis y en el párrafo segundo del apartado 1 del artículo 570 ter, tengan por finalidad o por objeto la comisión de alguno de los delitos tipificados en la sección siguiente."},{"ref":"Art. 572 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. Quienes promovieran, constituyeran, organizaran o dirigieran una organización o grupo terrorista serán castigados con las penas de prisión de ocho a quince años e inhabilitación absoluta durante el tiempo de la condena. 2. Quienes participaran activamente en la organización o grupo, o formaran parte de ellos, serán castigados con las penas de prisión de seis a doce años e inhabilitación absoluta durante el tiempo de la condena."}]}]},{"n":"7","title":"Els delictes de terrorisme i les seves penes","blocks":[{"text":"És delicte de terrorisme la comissió de qualsevol delicte greu de la llista de l''art. 573.1 (contra la vida, la llibertat, el patrimoni, la salut pública, d''atemptat, de tinença d''armes, etc.) amb alguna d''aquestes finalitats: 1a, subvertir l''ordre constitucional o desestabilitzar greument les institucions o estructures de l''Estat, o obligar els poders públics a fer o no fer un acte; 2a, alterar greument la pau pública; 3a, desestabilitzar greument una organització internacional, o 4a, provocar un estat de terror en la població. L''ànim de lucre no és una finalitat terrorista. També són terrorisme els delictes informàtics dels arts. 197 bis, 197 ter i 264 a 264 quater comesos amb aquestes finalitats (art. 573.2).","refs":[{"ref":"Art. 573.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª Subvertir el orden constitucional, o suprimir o desestabilizar gravemente el funcionamiento de las instituciones políticas o de las estructuras económicas o sociales del Estado, u obligar a los poderes públicos a realizar un acto o a abstenerse de hacerlo. 2.ª Alterar gravemente la paz pública. 3.ª Desestabilizar gravemente el funcionamiento de una organización internacional. 4.ª Provocar un estado de terror en la población o en una parte de ella."},{"ref":"Art. 573.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se considerarán igualmente delitos de terrorismo los delitos informáticos tipificados en los artículos 197 bis y 197 ter y 264 a 264 quater cuando los hechos se cometan con alguna de las finalidades a las que se refiere el apartado anterior."}]},{"text":"Penes (art. 573 bis): presó pel temps màxim previst al Codi si es causa la mort d''una persona; de vint a vint-i-cinc anys si en un segrest o detenció il·legal no es dona raó del parador de la persona; de quinze a vint anys per a lesions greus, segrest, estralls o incendi, i de deu a quinze anys per a altres lesions, detencions, amenaces o coaccions. Les penes s''imposen en la meitat superior si els fets es cometen contra les autoritats de l''art. 550.3, membres de les forces i cossos de seguretat o de les forces armades o empleats públics que presten servei en institucions penitenciàries. El dipòsit d''armes o explosius amb finalitat terrorista es castiga amb presó de vuit a quinze anys (art. 574.1).","refs":[{"ref":"Art. 573 bis.1.1a CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª Con la de prisión por el tiempo máximo previsto en este Código si se causara la muerte de una persona."},{"ref":"Art. 573 bis.1.2a CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"2.ª Con la de prisión de veinte a veinticinco años cuando, en los casos de secuestro o detención ilegal, no se dé razón del paradero de la persona."},{"ref":"Art. 573 bis.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las penas se impondrán en su mitad superior si los hechos se cometieran contra las personas mencionadas en el apartado 3 del artículo 550 o contra miembros de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas o contra empleados públicos que presten servicio en instituciones penitenciarias."},{"ref":"Art. 574.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"serán castigados con la pena de prisión de ocho a quince años cuando los hechos se cometan con cualquiera de las finalidades expresadas en el apartado 1 del artículo 573."}]}]},{"n":"8","title":"Adoctrinament, finançament, col·laboració i enaltiment del terrorisme","blocks":[{"text":"El Codi castiga també conductes anteriors a l''atemptat. L''adoctrinament o ensinistrament amb finalitat terrorista (art. 575, presó de dos a cinc anys) inclou accedir de manera habitual a serveis o continguts d''internet dirigits o idonis per incitar a incorporar-se a una organització terrorista o a col·laborar-hi, i traslladar-se o establir-se en un territori estranger amb aquesta finalitat. El finançament del terrorisme (art. 576) es castiga amb presó de cinc a deu anys i multa del triple al quíntuple, sense necessitat que els béns s''arribin a fer servir: si es posen a disposició del terrorista es pot imposar la pena superior en grau, i el subjecte obligat que per imprudència greu no el detecta té la pena inferior en un o dos graus. La col·laboració (art. 577) es castiga amb presó de cinc a deu anys.","refs":[{"ref":"Art. 575.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Se entenderá que comete este delito quien, con tal finalidad, acceda de manera habitual a uno o varios servicios de comunicación accesibles al público en línea o contenidos accesibles a través de internet o de un servicio de comunicaciones electrónicas cuyos contenidos estén dirigidos o resulten idóneos para incitar a la incorporación a una organización o grupo terrorista, o a colaborar con cualquiera de ellos o en sus fines."},{"ref":"Art. 575.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"La misma pena se impondrá a quien, para ese mismo fin, o para colaborar con una organización o grupo terrorista, o para cometer cualquiera de los delitos comprendidos en este Capítulo, se traslade o establezca en un territorio extranjero."},{"ref":"Art. 576 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con la pena de prisión de cinco a diez años y multa del triple al quíntuplo de su valor el que, por cualquier medio, directa o indirectamente, recabe, adquiera, posea, utilice, convierta, transmita o realice cualquier otra actividad con bienes o valores de cualquier clase con la intención de que se utilicen, o a sabiendas de que serán utilizados […] Si los bienes o valores se pusieran efectivamente a disposición del responsable del delito de terrorismo, se podrá imponer la pena superior en grado."},{"ref":"Art. 577.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1. Será castigado con las penas de prisión de cinco a diez años y multa de dieciocho a veinticuatro meses el que lleve a cabo, recabe o facilite cualquier acto de colaboración con las actividades o las finalidades de una organización, grupo o elemento terrorista"}]},{"text":"L''enaltiment o la justificació públics dels delictes terroristes o dels seus autors, o els actes de descrèdit, menyspreu o humiliació de les víctimes, es castiguen amb presó d''un a tres anys i multa de dotze a divuit mesos (art. 578.1), en la meitat superior si es fan per mitjans de comunicació, internet o serveis de comunicacions electròniques (art. 578.2).","refs":[{"ref":"Art. 578.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El enaltecimiento o la justificación públicos de los delitos comprendidos en los artículos 572 a 577 o de quienes hayan participado en su ejecución, o la realización de actos que entrañen descrédito, menosprecio o humillación de las víctimas de los delitos terroristas o de sus familiares, se castigará con la pena de prisión de uno a tres años y multa de doce a dieciocho meses."},{"ref":"Art. 578.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Las penas previstas en el apartado anterior se impondrán en su mitad superior cuando los hechos se hubieran llevado a cabo mediante la difusión de servicios o contenidos accesibles al público a través de medios de comunicación, internet, o por medio de servicios de comunicaciones electrónicas o mediante el uso de tecnologías de la información."}]}]},{"n":"9","title":"Conseqüències comunes dels delictes de terrorisme","blocks":[{"text":"Al condemnat a pena greu privativa de llibertat per terrorisme se li imposa a més la mesura de llibertat vigilada de cinc a deu anys, i d''un a cinc anys si la pena és menys greu (art. 579 bis.2). Els jutges poden rebaixar la pena en un o dos graus quan el fet és objectivament de menor gravetat, atesos el mitjà emprat o el resultat (art. 579 bis.4). La condemna d''un jutge o tribunal estranger s''equipara a les sentències espanyoles a l''efecte de la reincidència (art. 580). Les persones jurídiques responsables poden ser condemnades a multa de dos a cinc anys o del doble al quàdruple del perjudici si és més elevada, quan el delicte de la persona física té prevista una pena de més de dos anys (art. 580 bis). Els delictes de terrorisme que han causat la mort d''una persona no prescriuen (art. 131.3).","refs":[{"ref":"Art. 579 bis.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Al condenado a pena grave privativa de libertad por uno o más delitos comprendidos en este Capítulo se le impondrá además la medida de libertad vigilada de cinco a diez años, y de uno a cinco años si la pena privativa de libertad fuera menos grave."},{"ref":"Art. 579 bis.4 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"cuando el hecho sea objetivamente de menor gravedad, atendidos el medio empleado o el resultado producido."},{"ref":"Art. 580 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"En todos los delitos de terrorismo, la condena de un juez o tribunal extranjero será equiparada a las sentencias de los jueces o tribunales españoles a los efectos de aplicación de la agravante de reincidencia."},{"ref":"Art. 580 bis CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"a) Multa de dos a cinco años, o del doble al cuádruple del perjuicio causado cuando la cantidad resultante fuese más elevada, si el delito cometido por la persona física tiene prevista una pena de más de dos años de privación de libertad."},{"ref":"Art. 131.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Tampoco prescribirán los delitos de terrorismo, si hubieren causado la muerte de una persona."}]}]},{"n":"10","title":"La ciberdelinqüència (I): descobriment de secrets, accés il·legal i interceptació","blocks":[{"text":"El descobriment i la revelació de secrets castiga qui, per descobrir els secrets o vulnerar la intimitat d''un altre sense el seu consentiment, s''apodera dels seus papers, cartes, missatges de correu electrònic o altres documents, o n''intercepta les comunicacions: presó d''un a quatre anys i multa de dotze a vint-i-quatre mesos (art. 197.1). L''accés il·legal (intrusisme informàtic) castiga qui, vulnerant les mesures de seguretat i sense autorització, accedeix o facilita l''accés a un sistema d''informació o s''hi manté contra la voluntat del titular: presó de sis mesos a dos anys (art. 197 bis.1).","refs":[{"ref":"Art. 197.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que, para descubrir los secretos o vulnerar la intimidad de otro, sin su consentimiento, se apodere de sus papeles, cartas, mensajes de correo electrónico o cualesquiera otros documentos o efectos personales […] será castigado con las penas de prisión de uno a cuatro años y multa de doce a veinticuatro meses."},{"ref":"Art. 197 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que por cualquier medio o procedimiento, vulnerando las medidas de seguridad establecidas para impedirlo, y sin estar debidamente autorizado, acceda o facilite a otro el acceso al conjunto o una parte de un sistema de información o se mantenga en él en contra de la voluntad de quien tenga el legítimo derecho a excluirlo, será castigado con pena de prisión de seis meses a dos años."}]},{"text":"La interceptació de transmissions no públiques de dades informàtiques es castiga amb presó de tres mesos a dos anys o multa de tres a dotze mesos (art. 197 bis.2). Qui produeix, adquireix o facilita a tercers programes o contrasenyes per cometre aquests delictes, presó de sis mesos a dos anys o multa de tres a divuit mesos (art. 197 ter). L''estafa informàtica castiga qui, amb ànim de lucre i manipulant un sistema d''informació o dades, aconsegueix una transferència no consentida de qualsevol actiu patrimonial en perjudici d''un altre (art. 249.1.a).","refs":[{"ref":"Art. 197 bis.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con una pena de prisión de tres meses a dos años o multa de tres a doce meses."},{"ref":"Art. 197 ter CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con una pena de prisión de seis meses a dos años o multa de tres a dieciocho meses el que, sin estar debidamente autorizado, produzca, adquiera para su uso, importe o, de cualquier modo, facilite a terceros"},{"ref":"Art. 249.1.a) CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Los que, con ánimo de lucro, obstaculizando o interfiriendo indebidamente en el funcionamiento de un sistema de información o introduciendo, alterando, borrando, transmitiendo o suprimiendo indebidamente datos informáticos o valiéndose de cualquier otra manipulación informática o artificio semejante, consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro."}]}]},{"n":"11","title":"La ciberdelinqüència (II): els danys informàtics","blocks":[{"text":"Els danys informàtics castiguen qui, per qualsevol mitjà, sense autorització i de manera greu, esborra, danya, deteriora, altera, suprimeix o fa inaccessibles dades, programes informàtics o documents electrònics aliens, quan el resultat és greu: presó de sis mesos a tres anys (art. 264.1). La mateixa pena s''imposa per obstaculitzar o interrompre greument el funcionament d''un sistema informàtic aliè (art. 264 bis.1).","refs":[{"ref":"Art. 264.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que por cualquier medio, sin autorización y de manera grave borrase, dañase, deteriorase, alterase, suprimiese o hiciese inaccesibles datos informáticos, programas informáticos o documentos electrónicos ajenos, cuando el resultado producido fuera grave, será castigado con la pena de prisión de seis meses a tres años."},{"ref":"Art. 264 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"Será castigado con la pena de prisión de seis meses a tres años el que, sin estar autorizado y de manera grave, obstaculizara o interrumpiera el funcionamiento de un sistema informático ajeno"}]},{"text":"Són agreujants (art. 264.2), entre altres, cometre el fet en el marc d''una organització criminal, perjudicar greument el funcionament de serveis públics essencials o la provisió de béns de primera necessitat, i afectar el sistema informàtic d''una infraestructura crítica, que és un element o sistema essencial per al manteniment de funcions vitals de la societat, la salut, la seguretat, la protecció i el benestar econòmic i social de la població, la pertorbació o destrucció del qual tindria un impacte significatiu. L''edat de l''autor no és cap agreujant.","refs":[{"ref":"Art. 264.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"1.ª Se hubiese cometido en el marco de una organización criminal. […] 3.ª El hecho hubiera perjudicado gravemente el funcionamiento de servicios públicos esenciales o la provisión de bienes de primera necesidad. 4.ª Los hechos hayan afectado al sistema informático de una infraestructura crítica"},{"ref":"Art. 264.2.4a CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"A estos efectos se considerará infraestructura crítica un elemento, sistema o parte de este que sea esencial para el mantenimiento de funciones vitales de la sociedad, la salud, la seguridad, la protección y el bienestar económico y social de la población cuya perturbación o destrucción tendría un impacto significativo"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Organització criminal: més de dues persones, estable o per temps indefinit, amb repartiment de tasques per cometre delictes (art. 570 bis.1).","refs":[{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"la agrupación formada por más de dos personas con carácter estable o por tiempo indefinido"}]},{"text":"Grup criminal: més de dues persones sense alguna de les característiques de l''organització (art. 570 ter.1).","refs":[{"ref":"Art. 570 ter.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"sin reunir alguna o algunas de las características de la organización criminal"}]},{"text":"Dirigir una organització criminal per cometre delictes greus: presó de quatre a vuit anys (art. 570 bis.1).","refs":[{"ref":"Art. 570 bis.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"serán castigados con la pena de prisión de cuatro a ocho años si aquélla tuviere por finalidad u objeto la comisión de delitos graves"}]},{"text":"Blanqueig: presó de sis mesos a sis anys i multa del tant al triple; per imprudència greu, de sis mesos a dos anys (art. 301).","refs":[{"ref":"Art. 301.3 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"la pena será de prisión de seis meses a dos años y multa del tanto al triplo."}]},{"text":"Dirigir una organització terrorista: presó de vuit a quinze anys i inhabilitació absoluta (art. 572.1).","refs":[{"ref":"Art. 572 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"serán castigados con las penas de prisión de ocho a quince años e inhabilitación absoluta durante el tiempo de la condena."}]},{"text":"Terrorisme contra empleats públics d''institucions penitenciàries: pena en la meitat superior (art. 573 bis.2).","refs":[{"ref":"Art. 573 bis.2 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"o contra empleados públicos que presten servicio en instituciones penitenciarias."}]},{"text":"Enaltiment del terrorisme: presó d''un a tres anys i multa de dotze a divuit mesos (art. 578.1).","refs":[{"ref":"Art. 578.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"se castigará con la pena de prisión de uno a tres años y multa de doce a dieciocho meses."}]},{"text":"Reincidència en terrorisme: compten les condemnes estrangeres (art. 580).","refs":[{"ref":"Art. 580 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"la condena de un juez o tribunal extranjero será equiparada a las sentencias de los jueces o tribunales españoles"}]},{"text":"Accés il·legal a un sistema: presó de sis mesos a dos anys; danys informàtics greus: de sis mesos a tres anys (arts. 197 bis.1 i 264.1).","refs":[{"ref":"Art. 264.1 CP","law":"Codi penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"será castigado con la pena de prisión de seis meses a tres años."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
  from public.topics t where t.slug = 'pcat-e19-criminologia'
